          style={{
            fontFamily: "Syne, sans-serif",
            fontWeight: 700,
            fontSize: 30,
            lineHeight: 1.15,
            color: "var(--c-text)",
            margin: "56px 0 0",
            letterSpacing: "-0.02em",
          }}
