          width: 22,
          height: 22,
          flexShrink: 0,
          borderRadius: 11,
          background: "var(--c-primary)",
          color: "var(--c-bg)",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: selected ? 1 : 0,
          transition: "opacity 200ms ease",
        }}
      >
