            display: "flex",
            justifyContent: "center",
            marginBottom: 12,
            animation: "closerBounce 1.5s ease-in-out infinite",
          }}
        >
          <CloserCharacter state="celebration" size={86} />
        </div>
        <div
          style={{
            display: "flex",
            gap: 12,
            justifyContent: "center",
          }}
        >
          {[0, 1, 2].map((i) => {
            const earned = i < stars;
            return (
              <motion.span
                key={i}
                initial={{ scale: 0 }}
                animate={{ scale: [0, 1.2, 1] }}
                transition={{ duration: 0.4, ease: "easeOut" }}
