            lineHeight: 1.5,
            maxWidth: 400,
          }}
        >
          {subtitle}
        </div>

        {extra ? <div style={{ width: "100%", marginTop: 24 }}>{extra}</div> : null}

        <button type="button" onClick={onContinue} style={{ ...estiloBoton("principal"), marginTop: extra ? 24 : 40 }}>
          {buttonText.replace(/\s*→\s*$/, "")}
        </button>
      </div>
    </div>
  );
}

